from lib import *
S = SS('x111')
steps = [
    step("用 Spring Authorization Server(spring-boot-starter-oauth2-authorization-server)跑通授权码加 PKCE,客户端流程用 Python 手工走。公开客户端 demo(client-authentication-methods = none,require-proof-key = true,不要同意页)。客户端先生成 code_verifier(43 个字符),code_challenge = BASE64URL(SHA256(code_verifier)),method = S256,GET /oauth2/authorize 的跳转链是:302 到 /login → 登录(alice/pw)后 302 回 /oauth2/authorize → 302 到注册的 redirect_uri(…/cb?code=…&state=st1),code 长 128 个字符。再 POST /oauth2/token(grant_type = authorization_code、code、redirect_uri、client_id、code_verifier,没有 client_secret):HTTP 200,返回 access_token、id_token、scope、token_type = Bearer、expires_in = 299。access_token 是 RS256 的 JWT:header 里有 kid;claims 是 aud、exp、iat、iss、jti、nbf、scope、sub,iss = http://127.0.0.1:9601,sub = alice,aud = demo,有效期 300 秒;id_token 的 claims 有 aud、auth_time、azp、exp、iat、iss、jti、sid、sub。", t=tl(S(1)), mark=lidx(S(1), 'POST /oauth2/token', 'access_token 是 JWT'), done=lidx(S(1), 'GET /oauth2/authorize 的跳转链', '最终回到 redirect_uri', 'code_verifier 长度', 'id_token'), b=bars([['code_verifier 长度', 43, '43'], ['code 长度', 128, '128'], ['expires_in(秒)', 299, '299'], ['access_token 的有效期(秒)', 300, '300']], 300, done=[0, 1], mark=[2, 3]), kv=KV([['授权请求', 'code_challenge + S256,经 /login 回到 redirect_uri'], ['换令牌', '带 code_verifier,没有 client_secret'], ['access_token', 'RS256 的 JWT,300 秒,sub = alice,aud = demo'], ['id_token', '带 auth_time、azp、sid']], ['授权请求'])),
    step("各种错误。同一个 code 再换一次令牌:HTTP 400 {\"error\":\"invalid_grant\"}(授权码只能用一次);code_verifier 写错:HTTP 400 invalid_grant;换令牌时不带 code_verifier:HTTP 401,没有 body。授权请求里不带 code_challenge(公开客户端要求 PKCE):302 到注册的 redirect_uri?error=invalid_request&error_description=OAuth 2.0 Parameter: code_challenge;code_challenge_method = plain:同样 302 回去带 error=invalid_request、error_description 是 code_challenge_method。授权请求里的 redirect_uri 不是注册的那个:HTTP 500、一个 Whitelabel Error Page,没有重定向到那个未注册的地址——服务端不能把用户送到没注册的 URI。", t=tl(S(2)), mark=lidx(S(2), '换令牌时不带 code_verifier', 'redirect_uri 不是注册的那个'), done=lidx(S(2), '同一个 code 再换', 'code_verifier 写错', '不带 code_challenge', 'plain'), b=bars([['同一个 code 再换一次:状态码', 400, '400 invalid_grant'], ['code_verifier 写错:状态码', 400, '400 invalid_grant'], ['不带 code_verifier:状态码', 401, '401'], ['redirect_uri 未注册:状态码', 500, '500(不重定向)']], 500, done=[0, 1], mark=[2, 3]), kv=KV([['code', '只能用一次,第二次 invalid_grant'], ['code_verifier', '错了 invalid_grant,没带 401'], ['缺少 code_challenge / plain', '302 回 redirect_uri,带 error=invalid_request'], ['redirect_uri 不对', '不重定向,返回错误页']], ['code'])),
    step("刷新令牌与发现文档。公开客户端 demo 已经注册了 refresh_token 授权类型,令牌响应里却没有 refresh_token;scope 再加上 offline_access 之后,响应的字段仍是 access_token、expires_in、id_token、scope、token_type——公开客户端拿不到刷新令牌。换成机密客户端 conf(client_secret_basic)加 PKCE:响应里有 refresh_token;用它换新令牌:HTTP 200,新的 access_token 与旧的不同,但返回的 refresh_token 和旧的相同(默认复用刷新令牌);再用同一个旧的 refresh_token 换一次,仍然是 200;不带客户端凭据用 refresh_token:HTTP 401。/.well-known/openid-configuration:code_challenge_methods_supported 只有 [S256](没有 plain),grant_types_supported 有 authorization_code、client_credentials、refresh_token 和 token-exchange;/oauth2/jwks 有 1 把 RSA 密钥,kid 长 36。", t=tl(S(3)), mark=lidx(S(3), '公开客户端 demo', 'offline_access'), done=lidx(S(3), '机密客户端 conf', '用 refresh_token 换新令牌', '/.well-known/openid-configuration', '/oauth2/jwks'), b=bars([['公开客户端响应里的 refresh_token(1=有)', 0, '没有'], ['机密客户端响应里的 refresh_token', 1, '有'], ['换新令牌后 refresh_token 是否变化(1=变)', 0, '不变(复用)'], ['code_challenge_methods_supported 的个数', 1, '1(S256)']], 1, mark=[0, 2], done=[1, 3]), kv=KV([['公开客户端', '拿不到 refresh_token,即使注册了该类型也请求了 offline_access'], ['机密客户端', '有 refresh_token;默认换新时复用同一个'], ['发现文档', '只支持 S256 的 PKCE'], ['jwks', '1 把 RSA 密钥']], ['公开客户端'])),
]
A = mkartx('x111', 111, 'Spring,Security,OAuth2,PKCE,授权码,Authorization Server,真实验证,动画演示',
    '用 Spring Authorization Server 跑通授权码加 PKCE:公开客户端不需要 client_secret,换令牌必须带 code_verifier;授权码只能用一次;缺 code_challenge 或用 plain 会被拒绝;redirect_uri 未注册时不重定向;公开客户端拿不到 refresh_token,机密客户端的 refresh_token 默认被复用;access_token 是 300 秒的 RS256 JWT。',
    'PKCE 到底防什么?公开客户端为什么不需要 client_secret?授权码被截获了怎么办?为什么 SPA 拿不到刷新令牌?这篇在 Spring Boot 4.0.8 的 Spring Authorization Server 上,用 Python 手工走完整个授权码加 PKCE 的流程并逐个触发错误。',
    [('401 / invalid_grant', '换令牌时不带或写错 code_verifier,授权码都换不到令牌'), ('没有 refresh_token', '公开客户端即使注册了 refresh_token 类型、请求了 offline_access 也拿不到'), ('300 秒', 'access_token 的有效期(RS256 的 JWT)')],
    [('完整流程', '<p>授权请求带 code_challenge,登录后拿到 code,换令牌时带 code_verifier;返回 JWT 形式的 access_token 与 id_token。</p>'),
     ('各种错误', '<p>授权码只能用一次;code_verifier 缺失或错误换不到令牌;缺 code_challenge 或 plain 被拒绝;未注册的 redirect_uri 不重定向。</p>'),
     ('刷新令牌与发现文档', '<p>公开客户端拿不到 refresh_token;机密客户端换新令牌时复用同一个 refresh_token;发现文档只支持 S256。</p>')],
    steps,
    [ENV_X + '(Spring Security 7.0.7,Spring Authorization Server,通过 Boot 的 spring.security.oauth2.authorizationserver.* 配置两个客户端:公开客户端 demo 与机密客户端 conf)。浏览器的部分由 Python 手工模拟(授权请求要带 Accept: text/html 才会 302 到登录页);redirect_uri 是一个没有真正监听的地址,只读 Location;用户 alice / pw',
     '没有验证:同意页(require-authorization-consent = true);刷新令牌轮换(reuse-refresh-tokens = false)后旧令牌的失效;令牌撤销与 introspection;client_credentials 授权类型;自定义 JWT 声明;用 Spring Security OAuth2 Client 作为真正的客户端(见第 112 篇);redirect_uri 未注册时 Whitelabel 页面的原因(只观察到 500);OIDC 注销与会话管理'],
    '授权码加 PKCE')
